import * as fs from "node:fs";
import * as path from "node:path";
import * as vscode from "vscode";

/**
 * A webview panel that browses a folder of HTML pages generated by Inform:
 * the documentation, or a project's Index.
 *
 * A webview cannot follow links between local pages, so each page is read
 * here and given a content security policy, a <base> for its relative
 * resources, and a small script that sends link clicks back to the extension.
 * The pages' own scripts still run, so their show-and-hide boxes behave as in
 * the IDE. Their IDE hooks are provided: window.Project.pasteCode, behind
 * every "paste" button, pastes into the Inform source.
 *
 * Panels keep their own history for Back and Forward, and a Site says where
 * the pages are, how to point their resource paths at the webview, and what
 * to do with links in schemes of the IDE's own (source:, inform:).
 */
export interface Site {
  viewType: string;
  /** Panel title for a page without a <title>. */
  title: string;
  /** Folder the pages come from; links cannot leave it. */
  root: string;
  /** Folders the page may load resources from, root included. */
  resourceRoots: string[];
  home: string;
  /** Panel title for a page whose <title> is empty. */
  pageTitle?(page: string): string;
  /** Pages offered by Go to... */
  contents: { label: string; page: string }[];
  /** Point the page's own resource paths at webview URIs, from a file path. */
  rewrite?(html: string, uri: (file: string) => string): string;
  /** A link in a scheme other than http(s): or javascript:. */
  onLink?(href: string, from: PagePanel): void;
}

/** Paste code escapes characters as [=0xNNNN=]; turn them back. */
export function decodePasteCode(code: string): string {
  return code.replace(/\[=0x([0-9A-Fa-f]{4})=\]/g, (_, hex: string) =>
    String.fromCharCode(parseInt(hex, 16)),
  );
}

/**
 * Runs inside each page, ahead of the page's own scripts.
 *
 * Clicks are handled in the bubbling phase, so the pages' own onclick
 * handlers (showing and hiding boxes) run first, and propagation stops at
 * the document so VS Code's handler on the window never sees them: it would
 * try to open page links as files and cancel javascript: links.
 */
function pageScript(search: string, hash: string): string {
  const json = (s: string) => JSON.stringify(s).replace(/</g, "\\u003c");
  return `(function () {
  var vscode = acquireVsCodeApi();
  var hash = ${json(hash)};
  // The pages read their query through location.search, rewritten to this.
  window.__informSearch = ${json(search)};
  window.Project = {
    selectView: function () {},
    pasteCode: function (code) { vscode.postMessage({ type: "paste", code: String(code) }); },
    // Example links in the Windows IDE's documentation; not supported yet.
    createNewProject: function () {}
  };
  function scrollTo(id) {
    var target = document.getElementById(id) || document.getElementsByName(id)[0];
    if (target) { target.scrollIntoView(); }
  }
  function route(href) {
    if (href.charAt(0) === "#") {
      // With a <base>, the browser would resolve this against the base folder.
      scrollTo(decodeURIComponent(href.slice(1)));
    } else if (/^https?:/i.test(href)) {
      vscode.postMessage({ type: "external", url: href });
    } else if (/^[a-z][a-z0-9+.-]*:/i.test(href)) {
      vscode.postMessage({ type: "link", href: href });
    } else {
      vscode.postMessage({ type: "navigate", href: href });
    }
  }
  // The pages' window.location = '...' assignments, rewritten to this.
  window.__informGo = route;
  if (hash) {
    // The documentation's own onload opens the example named in location.hash.
    try { history.replaceState(null, "", "#" + hash); } catch (e) {}
    window.addEventListener("load", function () { scrollTo(hash); });
  }
  document.addEventListener("click", function (event) {
    var link = event.target && event.target.closest && event.target.closest("a[href]");
    if (!link) { return; }
    event.stopPropagation();
    var href = link.getAttribute("href");
    if (/^javascript:/i.test(href) || event.defaultPrevented) { return; }
    event.preventDefault();
    route(href);
  });
  window.addEventListener("mouseup", function (event) {
    if (event.button === 3) { vscode.postMessage({ type: "back" }); }
    if (event.button === 4) { vscode.postMessage({ type: "forward" }); }
  });
})();`;
}

/**
 * Make a page displayable in the webview: a content security policy, a base
 * for its relative resources, readable colours, our script, and the pages'
 * navigation through window.location and their reading of location.search
 * redirected to it.
 */
export function preparePage(
  html: string,
  page: { baseUri: string; cspSource: string; search: string; hash: string },
): string {
  // The pages' scripts are inline, and so are their onclick handlers and
  // javascript: links; they are local files, from Inform or its compiler.
  const csp = [
    "default-src 'none'",
    `img-src ${page.cspSource} data:`,
    `style-src ${page.cspSource} 'unsafe-inline'`,
    `font-src ${page.cspSource}`,
    "script-src 'unsafe-inline'",
  ].join("; ");
  // VS Code styles every webview from the colour theme: text in the editor's
  // foreground colour, links in its link colour, blockquotes tinted. The
  // pages are white paper that sets no body text colour, so in a dark theme
  // their text came out light gray on white. Put back a browser's defaults;
  // the pages' own styles, which follow, still have the last word.
  const defaults =
    "body { color: #000000; }" +
    " a, a:hover { color: #0000ee; }" +
    " blockquote { background: transparent; border-color: transparent; }";
  const head =
    `\n<meta http-equiv="Content-Security-Policy" content="${csp}">` +
    `\n<base href="${page.baseUri}/">` +
    `\n<style>${defaults}</style>` +
    `\n<script>${pageScript(page.search, page.hash)}</script>`;
  return html
    .replace(
      /window\.location\s*=\s*(['"])([^'"]*)\1/g,
      (_, quote: string, href: string) => `__informGo(${quote}${href}${quote})`,
    )
    .replace(/\blocation\.search\b/g, "__informSearch")
    .replace(/<head[^>]*>/i, (tag) => tag + head);
}

// The Inform source editor last used, to paste into while a page panel has
// the focus.
let lastSourceEditor: vscode.TextEditor | undefined;

function isInformSource(editor: vscode.TextEditor | undefined) {
  return (
    !!editor &&
    ["inform7", "inform7extension"].includes(editor.document.languageId)
  );
}

export function trackSourceEditors(): vscode.Disposable {
  if (isInformSource(vscode.window.activeTextEditor)) {
    lastSourceEditor = vscode.window.activeTextEditor;
  }
  return vscode.window.onDidChangeActiveTextEditor((editor) => {
    if (isInformSource(editor)) {
      lastSourceEditor = editor;
    }
  });
}

/** Paste at the cursor of the Inform source, replacing any selection, and show it. */
export async function pasteIntoSource(code: string) {
  const target =
    (lastSourceEditor && !lastSourceEditor.document.isClosed
      ? lastSourceEditor
      : undefined) ?? vscode.window.visibleTextEditors.find(isInformSource);
  if (!target) {
    vscode.window.showWarningMessage(
      "Open an Inform 7 source file to paste into.",
    );
    return;
  }
  const editor = await vscode.window.showTextDocument(
    target.document,
    target.viewColumn,
  );
  await editor.edit((edit) => edit.replace(editor.selection, code));
}

export class PagePanel {
  /** One panel per view type. */
  private static readonly panels = new Map<string, PagePanel>();

  /** Pages visited, relative to the root with forward slashes, with any ?query and #fragment. */
  private history: string[] = [];
  private position = -1;

  private constructor(
    readonly panel: vscode.WebviewPanel,
    readonly site: Site,
  ) {
    panel.webview.onDidReceiveMessage((message) => this.receive(message));
    panel.onDidChangeViewState(() => PagePanel.updateContext());
    panel.onDidDispose(() => {
      if (PagePanel.panels.get(site.viewType) === this) {
        PagePanel.panels.delete(site.viewType);
      }
      PagePanel.updateContext();
    });
  }

  /**
   * Show a site's panel at a page, its home by default. A panel already
   * showing another root (another project's Index, say) is replaced.
   */
  static open(
    site: Site,
    page = site.home,
    column: vscode.ViewColumn = vscode.ViewColumn.Beside,
  ): PagePanel {
    let current = PagePanel.panels.get(site.viewType);
    if (current && current.site.root !== site.root) {
      PagePanel.panels.delete(site.viewType);
      current.panel.dispose();
      current = undefined;
    }
    if (!current) {
      const panel = vscode.window.createWebviewPanel(
        site.viewType,
        site.title,
        { viewColumn: column, preserveFocus: false },
        {
          enableScripts: true,
          enableFindWidget: true,
          retainContextWhenHidden: true,
          localResourceRoots: site.resourceRoots.map((r) => vscode.Uri.file(r)),
        },
      );
      current = new PagePanel(panel, site);
      PagePanel.panels.set(site.viewType, current);
    } else {
      current.panel.reveal();
    }
    current.go(page);
    return current;
  }

  static get(viewType: string): PagePanel | undefined {
    return PagePanel.panels.get(viewType);
  }

  /** The panel with the focus, for the title-bar commands. */
  static active(): PagePanel | undefined {
    return [...PagePanel.panels.values()].find((p) => p.panel.active);
  }

  back() {
    this.step(-1);
  }

  forward() {
    this.step(1);
  }

  async goTo() {
    const choice = await vscode.window.showQuickPick(this.site.contents, {
      placeHolder: "Go to",
    });
    if (choice) {
      this.go(choice.page);
    }
  }

  /**
   * Show the current page again, after its files have changed; quietly, as
   * a page can be missing for a moment while the compiler rewrites them.
   */
  reload() {
    if (this.position >= 0) {
      this.render(true);
    }
  }

  private go(page: string) {
    this.history.splice(this.position + 1, Infinity, page);
    this.position = this.history.length - 1;
    this.render();
  }

  private step(delta: number) {
    const next = this.position + delta;
    if (next >= 0 && next < this.history.length) {
      this.position = next;
      this.render();
    }
  }

  private render(quiet = false) {
    const { page, search, hash } = splitEntry(this.history[this.position]);
    const file = path.join(this.site.root, page);
    let html: string;
    try {
      html = fs.readFileSync(file, "utf8");
    } catch {
      if (!quiet) {
        vscode.window.showErrorMessage(`Page not found: ${file}`);
      }
      return;
    }
    const webview = this.panel.webview;
    const uri = (f: string) =>
      webview.asWebviewUri(vscode.Uri.file(f)).toString();
    const rewritten = this.site.rewrite ? this.site.rewrite(html, uri) : html;
    webview.html = preparePage(rewritten, {
      baseUri: uri(path.dirname(file)),
      cspSource: webview.cspSource,
      search,
      hash,
    });
    const title = /<title>([^<]*)<\/title>/i.exec(html)?.[1].trim();
    this.panel.title = title || this.site.pageTitle?.(page) || this.site.title;
    PagePanel.updateContext();
  }

  private async receive(message: {
    type?: string;
    href?: string;
    url?: string;
    code?: string;
  }) {
    switch (message?.type) {
      case "navigate":
        this.follow(String(message.href));
        break;
      case "link":
        this.site.onLink?.(String(message.href), this);
        break;
      case "external":
        if (/^https?:/i.test(String(message.url))) {
          vscode.env.openExternal(vscode.Uri.parse(String(message.url)));
        }
        break;
      case "paste":
        await pasteIntoSource(decodePasteCode(String(message.code)));
        break;
      case "back":
        this.step(-1);
        break;
      case "forward":
        this.step(1);
        break;
    }
  }

  /**
   * A link relative to the current page. Only pages inside the root; a link
   * that names a missing file is tried from the root too, as some Index
   * detail pages give root-relative links in relative form.
   */
  private follow(href: string) {
    const { page: target, search, hash } = splitEntry(href);
    const current = splitEntry(this.history[this.position]).page;
    let page: string;
    try {
      page = path.posix.normalize(
        path.posix.join(path.posix.dirname(current), decodeURI(target)),
      );
      if (!fs.existsSync(path.join(this.site.root, page))) {
        page = path.posix.normalize(decodeURI(target));
      }
    } catch {
      return;
    }
    if (page.startsWith("..") || !/\.html?$/i.test(page)) {
      return;
    }
    this.go(page + search + (hash ? `#${hash}` : ""));
  }

  private static updateContext() {
    const active = PagePanel.active();
    vscode.commands.executeCommand(
      "setContext",
      "informEcosystem.pageCanGoBack",
      !!active && active.position > 0,
    );
    vscode.commands.executeCommand(
      "setContext",
      "informEcosystem.pageCanGoForward",
      !!active && active.position < active.history.length - 1,
    );
  }
}

/** "page.html?query#fragment" into its parts; search keeps its "?". */
function splitEntry(entry: string) {
  const m = /^([^?#]*)(\?[^#]*)?(?:#(.*))?$/.exec(entry);
  return { page: m?.[1] ?? entry, search: m?.[2] ?? "", hash: m?.[3] ?? "" };
}

export function registerPageCommands(): vscode.Disposable[] {
  return [
    trackSourceEditors(),
    vscode.commands.registerCommand("informEcosystem.pageBack", () =>
      PagePanel.active()?.back(),
    ),
    vscode.commands.registerCommand("informEcosystem.pageForward", () =>
      PagePanel.active()?.forward(),
    ),
    vscode.commands.registerCommand("informEcosystem.pageGoTo", () =>
      PagePanel.active()?.goTo(),
    ),
  ];
}
